"""Self-check for gradle_verification_variants.py without network access.

Pins the rewrite (a differing Portal copy becomes <also-trust> next to the existing value, a second
run adds nothing, files the Portal leaves to Central stay untouched), the warning for entries in
another layout, and which Portal responses count as the Portal's own copy.
"""

import hashlib
import importlib.util
import sys
from pathlib import Path

SCRIPT = Path(__file__).resolve().parent / "gradle_verification_variants.py"
SPEC = importlib.util.spec_from_file_location("gradle_verification_variants", SCRIPT)
variants = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(variants)

CENTRAL_POM = b"<project>central</project>"
PORTAL_POM = b"<project>portal</project>"


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


METADATA = f"""<?xml version="1.0" encoding="UTF-8"?>
<verification-metadata xmlns="https://schema.gradle.org/dependency-verification">
   <components>
      <component group="org.example" name="marker" version="1.0">
         <artifact name="marker-1.0.pom">
            <sha256 value="{sha(CENTRAL_POM)}" origin="Generated by Gradle"/>
         </artifact>
      </component>
      <component group="org.example" name="lib" version="2.0">
         <artifact name="lib-2.0.jar">
            <sha256 value="{"a" * 64}" origin="Generated by Gradle"/>
         </artifact>
      </component>
   </components>
</verification-metadata>
"""


def run(monkeypatch, path: Path) -> None:
    def portal_copy(url):
        return PORTAL_POM if url.endswith("marker-1.0.pom") else None

    def fetch(opener, url):
        return (200, CENTRAL_POM) if url.endswith("marker-1.0.pom") else (404, b"")

    monkeypatch.setattr(variants, "portal_copy", portal_copy)
    monkeypatch.setattr(variants, "fetch", fetch)
    monkeypatch.setattr(sys, "argv", ["gradle_verification_variants.py", str(path)])
    variants.main()


def test_portal_variant_becomes_also_trust_once(tmp_path, monkeypatch):
    path = tmp_path / "verification-metadata.xml"
    path.write_text(METADATA, encoding="utf-8")

    run(monkeypatch, path)
    first = path.read_text(encoding="utf-8")
    assert (
        f'            <sha256 value="{sha(CENTRAL_POM)}" origin="Generated by Gradle">\n'
        f'               <also-trust value="{sha(PORTAL_POM)}"/>\n'
        "            </sha256>\n"
    ) in first
    assert f'<sha256 value="{"a" * 64}" origin="Generated by Gradle"/>' in first

    run(monkeypatch, path)
    assert path.read_text(encoding="utf-8") == first


def test_entry_in_other_layout_is_reported(tmp_path, monkeypatch, capsys):
    path = tmp_path / "verification-metadata.xml"
    path.write_text(
        METADATA.replace(f'<sha256 value="{"a" * 64}"', f'<sha512 value="{"a" * 128}"'),
        encoding="utf-8",
    )
    run(monkeypatch, path)
    output = capsys.readouterr().out
    assert "::warning::" in output
    assert "org.example:lib:2.0 lib-2.0.jar" in output


def responses(monkeypatch, table):
    calls = []

    def fetch(opener, url):
        calls.append((opener, url))
        return table[url]

    monkeypatch.setattr(variants, "fetch", fetch)
    return calls


def test_portal_copy_served_directly(monkeypatch):
    responses(monkeypatch, {"https://plugins.gradle.org/m2/a.pom": (200, b"own")})
    assert variants.portal_copy("https://plugins.gradle.org/m2/a.pom") == b"own"


def test_portal_redirect_to_central_is_no_own_copy(monkeypatch):
    calls = responses(
        monkeypatch,
        {
            "https://plugins.gradle.org/m2/a.pom": (
                303,
                b"https://repo.maven.apache.org/maven2/a.pom",
            )
        },
    )
    assert variants.portal_copy("https://plugins.gradle.org/m2/a.pom") is None
    assert len(calls) == 1


def test_portal_redirect_to_own_storage_is_followed(monkeypatch):
    storage = "https://plugins-artifacts.gradle.org/org.example/a/1.0/abc/a.jar"
    calls = responses(
        monkeypatch,
        {
            "https://plugins.gradle.org/m2/a.jar": (303, storage.encode()),
            storage: (200, b"stored"),
        },
    )
    assert variants.portal_copy("https://plugins.gradle.org/m2/a.jar") == b"stored"
    assert calls[1] == (variants.FOLLOW, storage)


def test_missing_on_portal_is_no_copy(monkeypatch):
    responses(monkeypatch, {"https://plugins.gradle.org/m2/a.pom": (404, b"")})
    assert variants.portal_copy("https://plugins.gradle.org/m2/a.pom") is None
